contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(new __InvMutHandleStub())); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function test(address member, uint amount) external {
        c.mintSynth(member, amount); if (__ESBMC_reverted()) return;
        bool burnReverted;
        c.burnSynth(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { burnReverted = true; } else { burnReverted = false; }
        assert(c.totalSupply() == amount || burnReverted);
    }
}

