pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Synth c;

    function setUp() public {
        c = new Synth();
    }

    function _test(address member, uint256 amount) internal {
        c.mintSynth(member, amount);
        bool burnReverted;
        try c.burnSynth() { burnReverted = false; } catch { burnReverted = true; }
        assertTrue(c.totalSupply() == amount || burnReverted);
    }

    function testFuzz_test(address member, uint256 amount) public {
        vm.assume(member.code.length == 0 && uint160(member) > 0xffff && member != address(this) && member != address(c) && member != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && member != 0x000000000000000000636F6e736F6c652e6c6f67 && member != 0x4e59b44847b379578588920cA78FbF26c0B4956C && member != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(member, amount);
    }
}
